EOF
q(){ curl -s -A "$UA" "https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=$1&gsrnamespace=6&gsrlimit=${2:-12}&prop=imageinfo&iiprop=url%7Cextmetadata%7Csize%7Cmime&iiurlwidth=1280&format=json" -o "dl/s_$3.json"; echo "=== $1"; node cs.js "dl/s_$3.json"; }
